            else:ordered.append(dep)
        labels=' '.join(BY_NAME[n].label for n in dict.fromkeys(ordered))
        fail('the following required arguments were not provided:\n'+''.join('  '+BY_NAME[n].label+'\n' for n in required).rstrip(),prog+' '+labels+' [PATH]')
    if cfg.print_completions:show_doc('completions-'+cfg.print_completions+'.txt',prog)
    if cfg.print_manpage:show_doc('manpage.txt',prog)
    for s in cfg.auth:
        cfg.credentials.append(credential(s))
    if cfg.auth_file:
        try:
            for line in open(cfg.auth_file,encoding='utf-8').read().splitlines():
