            else:
                key,value=next(iter(data.items()))
                if key!='DirSize':
                    end=body.find('"',body.find('"')+1)+1
                    error=f'unknown variant `{key}`, expected `DirSize` at line 1 column {end}'
                elif not isinstance(value,str):
