    def remove(self):
        rel=self.query_path()
        if rel is None:return
        parts=storage.normalize_path(rel)
        normalized='/'+'/'.join(parts)
        if not render.path_allowed(normalized,self.cfg.rm_files):
            self.error(403,'Deletion not allowed in this directory');return
        if not self.cfg.hidden and any(p.startswith('.') for p in parts):
            self.error(400,"Invalid path\ncaused by: Invalid value for 'path' parameter");return
