            self.error(500,'Failed to delete file\ncaused by: '+e.strerror+f' (os error {e.errno})');return
        self.reply(303,b'',{'location':self.headers.get('Referer','/')})


class Server(ThreadingHTTPServer):
    daemon_threads=True
    allow_reuse_address=True
    request_queue_size=128

    def handle_error(self,request,client_address):
        pass


class Server6(Server):
    address_family=socket.AF_INET6
    def server_bind(self):
        self.socket.setsockopt(socket.IPPROTO_IPV6,socket.IPV6_V6ONLY,1)
        super().server_bind()


def log_error(message):
    stamp=time.strftime('%a, %d %b %Y %H:%M:%S %z')
    for line in message.split('\n'):print(stamp+' [ERROR] '+line,file=sys.stderr,flush=True)
    print('Error: '+message,file=sys.stderr,flush=True)


def run(cfg):
    path=cfg.path if cfg.path is not None else '.'
    try:
        # realpath alone does not report a nonexistent final path component.
        root=os.path.realpath(path)
        os.stat(root)
    except OSError as e:
        log_error('Failed to resolve path to be served\ncaused by: '+e.strerror+f' (os error {e.errno})')
        return 1
    cfg.root=root
    cfg.single_file=os.path.isfile(root)
    cfg.prefix=('/'+cfg.route_prefix.strip('/')) if cfg.route_prefix and cfg.route_prefix.strip('/') else ''
    if cfg.random_route:cfg.prefix='/'+os.urandom(3).hex()
    if cfg.index and not os.path.exists(os.path.join(root,cfg.index)):
        print(time.strftime('%a, %d %b %Y %H:%M:%S %z')+" [WARN] The file '"+cfg.index+"' provided for option --index could not be found.",flush=True)
    print('miniserve v0.32.0',flush=True)
    if cfg.path is None and not cfg.index and not sys.stdin.isatty():
        log_error('Refusing to start as no explicit serve path was set and no interactive terminal was attached\nPlease set an explicit serve path like: `miniserve /my/path`')
        return 1
    old_umask=os.umask(0);os.umask(old_umask)
    cfg.file_mode=0o666&~old_umask
    interfaces=cfg.interfaces or ['::','0.0.0.0']
    servers=[]
    context=None
    if cfg.tls_cert and cfg.tls_key:
        try:
            context=ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
            context.load_cert_chain(cfg.tls_cert,cfg.tls_key)
        except (OSError,ssl.SSLError) as e:
            log_error('Failed to configure TLS\ncaused by: '+str(e));return 1
    try:
        for iface in interfaces:
            cls=Server6 if ':' in iface else Server
            server=cls((iface,cfg.port),Handler)
            server.cfg=cfg
            if context:server.socket=context.wrap_socket(server.socket,server_side=True)
            servers.append(server)
    except OSError as e:
        for server in servers:server.server_close()
        log_error('Failed to bind to address\ncaused by: '+e.strerror+f' (os error {e.errno})')
        return 1
    bound=[];available=[]
    scheme='https' if context else 'http'
    for server,iface in zip(servers,interfaces):
        port=server.server_port
        bound.append(('['+iface+']' if ':' in iface else iface)+':'+str(port))
        if iface=='::':hosts=['::1']
        elif iface=='0.0.0.0':hosts=['127.0.0.1']
        else:hosts=[iface]
        for host in hosts:
            address=scheme+'://'+('['+host+']' if ':' in host else host)+':'+str(port)+cfg.prefix
            if address not in available:available.append(address)
    # The default enumeration lists loopback IPv4 before IPv6.
    if not cfg.interfaces:available.sort(key=lambda x:'[' in x)
    print('Bound to '+', '.join(bound),flush=True)
    print('Serving path '+root,flush=True)
    print('Available at (non-exhaustive list):',flush=True)
    for address in available:print('    '+address,flush=True)
    print(flush=True)
    stopping=threading.Event()
    def stop(signum,frame):stopping.set()
    signal.signal(signal.SIGTERM,stop)
    signal.signal(signal.SIGINT,stop)
    for server in servers:
        thread=threading.Thread(target=server.serve_forever,kwargs={'poll_interval':.1},daemon=True)
        thread.start()
    stopping.wait()
    for server in servers:server.shutdown();server.server_close()
    return 0
