    def upload(self):
        rel=self.query_path()
        if rel is None:return
        parts=storage.normalize_path(rel)
        rel_normal='/'+'/'.join(parts)
        if not render.path_allowed(rel_normal,self.cfg.upload_files):
            self.error(403,'Upload not allowed to this directory');return
        disk=os.path.join(self.cfg.root,*parts)
        if not os.path.exists(disk) or not storage.within(disk,self.cfg.root):
            self.error(400,"Invalid HTTP request\ncaused by: Invalid value for 'path' parameter");return
        if not os.path.isdir(disk):
            self.error(400,"Invalid path\ncaused by: cannot upload file to "+disk+", since it's not a directory");return
        if not self.cfg.hidden and any(s.startswith('.') for s in parts):
            self.error(400,"Invalid path\ncaused by: Invalid value for 'path' parameter");return
        function=self.headers.get('X-File-Hash-Function')
