                    self.error(403,'Insufficient permissions to create file in '+disk+('/' if not parts else ''));return
                try:dirname=data.decode('utf-8')
                except UnicodeError:
                    self.error(400,'Invalid path\ncaused by: Invalid directory name');return
                dirparts=storage.normalize_path(dirname)
                if not self.cfg.hidden and any(s.startswith('.') for s in dirparts):
                    self.error(400,'Invalid path\ncaused by: Invalid directory name');return
                try:os.makedirs(os.path.join(disk,*dirparts),exist_ok=True)
